      msteps SEGS (mkst regs (0x1b504 : word) m rom) (mkst regs' (0x197ec : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x1b510 /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 pixs
      /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs'.
